package com.example.microsave.member.controller;
import com.example.microsave.member.dto.MemberDTO; import com.example.microsave.member.service.MemberService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/members") public class MemberController {private final MemberService s; public MemberController(MemberService s){this.s=s;} @GetMapping public List<MemberDTO> all(){return s.all();} @GetMapping("/{id}") public MemberDTO one(@PathVariable Long id){return s.one(id);} @GetMapping("/group/{groupId}") public List<MemberDTO> group(@PathVariable Long groupId){return s.byGroup(groupId);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public MemberDTO save(@Valid @RequestBody MemberDTO d){return s.save(d);} @PutMapping("/{id}") public MemberDTO update(@PathVariable Long id,@Valid @RequestBody MemberDTO d){return s.update(id,d);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.delete(id);}}
